"""AQS-PRO-001 plant BOM roll-up (X-PRO-01, partial until every unit has its bom.csv under unit task 12). Rolls up every unit
models/mfg/<UNIT>/bom.csv, the motor family BOMs (models/motors/MF-nn/bom.csv x family count, AQS-INV-005), and the bulk
inventories: pipe (AQS-INV-003), wire (AQS-INV-002) and other building blocks (AQS-INV-004). Lists the graph units that have
no BOM yet. Writes docs-authority/PLANT_BOM.md and docs-authority/inventory/PLANT_BOM.csv. Run: python3 docs-authority/_plant_bom.py"""
import csv, glob, json, os, collections
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); os.chdir(R)
I = 'docs-authority/inventory/'
rows = []
# the roster is the graph (AQS-GOV authority): present units only. Model
# directories of retired units stay on disk as artifacts but leave the plant
# bill of materials, which is the buildable plant.
_g = json.load(open('flow_graph/plant_flow_graph.json'))
PRESENT = {n['unit_id'] for n in _g['nodes'] if n.get('presence') == 'present'}
for f in sorted(glob.glob('models/mfg/*/bom.csv')):
    u = f.split('/')[2]
    if u not in PRESENT: continue
    for r in csv.DictReader(open(f, newline='')):
        r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
        rows.append(dict(source='unit', unit=u, item=r.get('description') or r.get('part', ''), qty=r.get('qty', ''), material=r.get('material', ''),
                         basis=r.get('basis') or r.get('make_or_buy', '')))
for f in sorted(glob.glob('models/units/*/bom.csv')):
    u = f.split('/')[2]
    if u not in PRESENT: continue
    for r in csv.DictReader(open(f, newline='')):
        if r['basis'].startswith(('AQS-INV-001', 'AQS-INV-004')): continue   # counted once in the motor family and building-block roll-ups
        rows.append(dict(source='unit envelope BOM', unit=u, item=r['description'], qty=r['qty'], material=r['material'], basis=r['basis']))
fam = {r['family']: r for r in csv.DictReader(open(I + 'MOTOR_FAMILIES.csv'))}
for f in sorted(glob.glob('models/motors/MF-*/bom.csv')):
    m = f.split('/')[2]; n = int(fam[m]['count']) if m in fam else 0
    for r in csv.DictReader(open(f)):
        q = r['qty']; qt = (str(int(float(q))*n) if q.replace('.', '', 1).isdigit() else q)
        rows.append(dict(source='motor family', unit=f"{m} x {n}", item=r['description'], qty=qt, material='', basis=r.get('basis', '')))
for r in csv.DictReader(open(I + 'PIPE_FAMILIES.csv')):
    rows.append(dict(source='bulk pipe', unit=r['family'], item=f"{r['material']} DN{r['DN']} pipe, {r['stock_lengths_6m']} x 6.096 m", qty=f"{r['pipe_m']} m", material=r['material'], basis='AQS-INV-003'))
    rows.append(dict(source='bulk pipe', unit=r['family'], item=f"{r['elbow_std']}; {r['flange_std']}; gaskets; {r['stud_size']} studs", qty=f"{r['elbows_90']} / {r['flanges']} / {r['gaskets']} / {r['stud_bolts']}", material=r['material'], basis='AQS-INV-003'))
for r in csv.DictReader(open(I + 'WIRE_FAMILIES.csv')):
    rows.append(dict(source='bulk wire', unit=r['family'], item=f"{r['type']} {r['size']} {r['insulation']}, {r['voltage_class']}", qty=f"{r['conductor_m']} m", material='Cu', basis='AQS-INV-002'))
for r in csv.DictReader(open(I + 'OTHER_FAMILIES.csv')):
    rows.append(dict(source='building block', unit=r['family'], item=f"{r['category']}: {r['item']} ({r['spec']})", qty=r['qty'], material='', basis='AQS-INV-004'))
w = csv.DictWriter(open(I + 'PLANT_BOM.csv', 'w', newline=''), fieldnames=['source', 'unit', 'item', 'qty', 'material', 'basis']); w.writeheader(); w.writerows(rows)
g = json.load(open('flow_graph/plant_flow_graph.json'))
have = {f.split('/')[2] for f in glob.glob('models/mfg/*/bom.csv') + glob.glob('models/units/*/bom.csv')}
need = sorted(n['unit_id'] for n in g['nodes'] if n.get('presence') == 'present' and n.get('class') not in ('header', 'product', 'pv', 'sink', 'source') and n['unit_id'] not in have)
c = collections.Counter(r['source'] for r in rows)
md = ['# Plant BOM roll-up', '', 'Document number: AQS-PRO-001', 'Revision: A', 'Date: 2026-10-16', 'Authority: AQS-PLAN-007 X-PRO-01 (partial). Generated by `docs-authority/_plant_bom.py`. Full list in `docs-authority/inventory/PLANT_BOM.csv`.', '',
      '| Source | Lines |', '|---|---|'] + [f'| {k} | {v} |' for k, v in sorted(c.items())] + [f'| Total | {len(rows)} |', '',
      f"Unit BOMs: {len(glob.glob('models/mfg/*/bom.csv'))} CAD BOMs (models/mfg) and {len(glob.glob('models/units/*/bom.csv'))} envelope BOMs (models/units, A-M-183; motors and building blocks counted once in their family roll-ups). Motor families: {len(glob.glob('models/motors/MF-*/bom.csv'))}, quantities multiplied by the family count. Bulk pipe, wire and building blocks from AQS-INV-002..004.", '',
      f"## Units without a BOM yet ({len(need)})", '', 'These carry an envelope only; each gets its bom.csv at its unit task 12, and the roll-up picks it up on the next pipeline pass.', '', ', '.join(need)]
open('docs-authority/PLANT_BOM.md', 'w').write('\n'.join(md) + '\n'); print(len(rows), len(have), len(need))
